def find_path(graph, start, goal):
    # Initialize the path and visited set
    path = []
    visited = set()

    def search(node):
        if node in visited:
            return None
        if node == goal:
            return [node]
        visited.add(node)
        for next_node in graph[node]:
            path_found = search(next_node)
