    def explore(node):
        if node in visited:
            return False
        visited.add(node)
        if node == goal:
            return True
        for neighbor in graph.get(node, []):
            if explore(neighbor):
                path.append(node)
                return True
        return False

    if explore(start):
        return path[::-1]
    else:
        return None
