def find_path(graph, start, goal):
    # Initialize the stack for DFS, using a list
    stack = [(start, [start])]
    while stack:
        (node, path) = stack.pop()
        for next_node in set(graph.get(node, [])).difference(path):
            if next_node == goal:
                return path + [next_node]
            else:
                stack.append((next_node, path + [next_node]))
    return None
