def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the stack for BFS
    stack = [(start, [start])]
    visited = set()

    while stack:
        (node, path) = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == goal:
                return path
            for neighbor in graph[node]:
                stack.append((neighbor, path + [neighbor]))

    # If no path is found
    return None
